import{_ as t,o as d,c as o,a3 as i}from"./chunks/framework.I6s8z2kk.js";const v=JSON.parse('{"title":"Services","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/services.md","filePath":"dev/domain/services.md"}'),c={name:"dev/domain/services.md"};function a(r,e,s,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h1><p>A <strong>Service</strong> is something a center sells. Every service has a <code>type</code>, belongs to one center, and points to a type-specific record (its <em>serviceable</em>).</p><h2 id="service-types" tabindex="-1">Service types <a class="header-anchor" href="#service-types" aria-label="Permalink to &quot;Service types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Serviceable</th><th>Booked by</th></tr></thead><tbody><tr><td><code>recreation_riding</code></td><td><code>RecreationalRiding</code></td><td>Hourly slot with a schedule</td></tr><tr><td><code>visit</code></td><td><code>Visit</code></td><td>Day or specific time, shared daily capacity</td></tr><tr><td><code>event</code></td><td><code>Event</code></td><td>Ticket for a dated event</td></tr><tr><td><code>resort</code></td><td><code>Resort</code></td><td>A date range, priced per day, with add-ons</td></tr><tr><td><code>horse_care</code></td><td><code>HorseCare</code></td><td>Price options only</td></tr><tr><td><code>horse_service</code></td><td><code>HorseService</code></td><td>Price options only</td></tr><tr><td><code>training</code></td><td><code>TrainingService</code></td><td>Hourly slot with a trainer</td></tr><tr><td><code>membership</code></td><td><code>Membership</code></td><td>A paid membership with packages and visits</td></tr><tr><td><code>stabling</code></td><td><code>Stabling</code></td><td>A horse&#39;s stay, booked by the center: a monthly price, or an open-ended daily stay, plus extras</td></tr></tbody></table><p>Riding, visit, event, resort and training are bookable through reservations; stabling only by the center, for a horse. See <a href="./reservations">Reservations</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Scoped to the route center.</strong> Filter every center endpoint by <code>center_id</code> and validate every cross-reference (block <code>service_id</code>, membership <code>visit_service_id</code> and packages, training trainers) against the route center.</li><li><strong>Authorization by type.</strong> <code>Gate::authorize(&#39;manageServices&#39;, [$center, ServiceType::X])</code>. Trainers fall under Training. Center-wide blocks and gender periods need <code>manageAllServices</code>.</li><li><strong>Writes lock and keep identity.</strong> Create and update inside <code>DB::transaction</code> with <code>lockForUpdate</code> on the Service. New services start <code>ACTIVE</code>. <code>type</code>, <code>center_id</code> and <code>slug</code> never change on update.</li><li><strong>Price options update in place.</strong> Update duration price options by id so sold packages survive. Options missing from the payload are soft-deleted together with their package. There is one <code>ServicePackage</code> per price option; revive a trashed package instead of duplicating.</li><li><strong>Package status.</strong> A <code>ServicePackage</code> has a <code>status</code> (<code>ActivationStatus</code>, default <code>active</code>). <code>packages.*.status</code> is optional: when omitted, a live package keeps its status and a new or revived one is active. Inactive packages stay in the center resources but clients get <code>package: null</code> for them, and <code>ServicePackage::isSellable()</code> (active and not trashed) gates package purchases and membership availability.</li><li><strong>Settings</strong> are boolean rows unique per <code>(service_id, key)</code>, limited to the model&#39;s <code>SETTINGS_KEYS</code> (for example <code>enable_cash_on_arrival</code>, <code>enable_single_session_booking</code>, <code>enable_package_booking</code>).</li><li><strong>Stabling prices</strong> live in <code>price_options</code>, told apart by <code>unit</code>: monthly prices are <code>month</code> with <code>quantity</code> = months (1-24, at least one, distinct), the optional daily price is <code>day</code> with <code>quantity</code> 1, extras are <code>option</code> with a <code>name</code> and no quantity. The API exposes them as <code>monthly_prices</code>, <code>daily_price</code> and <code>extra_options</code>. <code>StablingService</code> updates them in place by <code>id</code> (an id of another service is a 422) and soft-deletes options missing from the payload.</li><li><strong>Deletion</strong> soft-deletes the service, its serviceable and its price options. History and analytics read <code>withTrashed()</code>.</li><li><strong>Visibility.</strong> Clients only see <code>ACTIVE</code> services of visible, active centers.</li></ul><h2 id="prices-on-the-client-api" tabindex="-1">Prices on the client API <a class="header-anchor" href="#prices-on-the-client-api" aria-label="Permalink to &quot;Prices on the client API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>start_price</code></td><td>Lowest price option in halalas. Built by <code>Service::withStartPrice()</code>: a Resort ignores add-ons and a Stabling ignores extras (price options with no quantity). <code>null</code> when there is none.</td></tr><tr><td><code>display_price</code></td><td><code>null</code>, or <code>{original, discounted, discount_amount, badge}</code> while an automatic offer lowers the start price right now.</td></tr></tbody></table><p><code>display_price</code> is returned by the homepage curated services, the offers list, the center details services and the service details endpoint. Prices inside <code>details.price_options</code> are not discounted.</p><h2 id="client-endpoints" tabindex="-1">Client endpoints <a class="header-anchor" href="#client-endpoints" aria-label="Permalink to &quot;Client endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET clients/services</code></td><td>Search across visible services</td></tr><tr><td><code>GET clients/centers/{center}/services/{slug}</code></td><td>Details with the type-specific <code>details</code>; riding, event and training include upcoming availability</td></tr><tr><td><code>GET clients/services/{service}/availability</code></td><td>Availability for booking</td></tr></tbody></table><h2 id="center-and-admin-endpoints" tabindex="-1">Center and admin endpoints <a class="header-anchor" href="#center-and-admin-endpoints" aria-label="Permalink to &quot;Center and admin endpoints&quot;">​</a></h2><p>Each type has CRUD under <code>centers/{center}/&lt;type&gt;</code> (<code>recreation-ridings</code>, <code>visits</code>, <code>events</code>, <code>resorts</code>, <code>horse-cares</code>, <code>horse-services</code>, <code>training-services</code>, <code>memberships</code>, <code>stablings</code>), mirrored under <code>admin/centers/{center}/...</code>. Also <code>trainers</code>, <code>service-blocks</code>, <code>periods</code>, <code>service-types</code> and <code>service-types/{type}/terms</code>.</p>',14)])])}const g=t(c,[["render",a]]);export{v as __pageData,g as default};
